(function(){
const verses=document.getElementById('verses'),player=document.getElementById('quran-audio');if(!verses||!player)return;
const $id=id=>document.getElementById(id),fmt=n=>Number.isFinite(n)?`${Math.floor(n/60)}:${String(Math.floor(n%60)).padStart(2,'0')}`:'0:00';let tafsirData,token=0;
const editions={'ar.alafasy':['ar.alafasy',128],'ar.abdulbasitmurattal':['ar.abdulbasitmurattal',192],'ar.husary':['ar.husary',128],'ar.minshawi':['ar.minshawi',128],'ar.abdurrahmaansudais':['ar.abdurrahmaansudais',192]};
const chapters={'ar.alafasy':7,'ar.abdulbasitmurattal':2,'ar.husary':6,'ar.minshawi':9,'ar.abdurrahmaansudais':3,'yasser-surah':97};
function current(){return window.selectedSurah?.()||state?.corpus?.surahs?.[state.selected-1]}
function url(s,a,id){if(id==='yasser-surah')return `https://everyayah.com/data/Yasser_Ad-Dussary_128kbps/${String(s.number).padStart(3,'0')}${String(a.number).padStart(3,'0')}.mp3`;const x=editions[id]||editions['ar.alafasy'];return `https://cdn.islamic.network/quran/audio/${x[1]}/${x[0]}/${a.global}.mp3`}
function clear(){verses.querySelectorAll('.is-playing').forEach(x=>x.classList.remove('is-playing'))}
function active(n,scroll=false){clear();const c=$id(`ayet-${n}`);c?.classList.add('is-playing');if(scroll)c?.scrollIntoView({behavior:'smooth',block:'center'});sync()}
function enhance(){const s=current();if(!s)return;verses.querySelectorAll('.verse').forEach((card,i)=>{const a=s.ayahs[i],actions=card.querySelector('.verse-actions');if(!a||!actions)return;
 card.querySelectorAll('.verse-inline-player').forEach(x=>x.remove());actions.querySelectorAll('[data-play-ayah]').forEach(x=>x.remove());card.querySelectorAll('[data-tafsir]').forEach(x=>{const box=x.nextElementSibling;if(box?.classList.contains('tafsir-box'))box.remove();x.remove()});
 if(!actions.querySelector('[data-v17-play]')){const b=document.createElement('button');b.type='button';b.dataset.v17Play=a.number;b.className='v17-sound';b.textContent='▶';b.title='Bu ayetten dinlemeye başla';b.setAttribute('aria-label',`${s.name} ${a.number}. ayeti dinle`);actions.prepend(b)}
 if(!card.querySelector('[data-v17-tafsir]')){const b=document.createElement('button');b.type='button';b.className='tafsir-toggle';b.dataset.v17Tafsir=a.number;b.textContent='Ayet tefsirini göster';const box=document.createElement('div');box.className='tafsir-box v17-tafsir';box.hidden=true;card.append(b,box)}
 if(!card.querySelector('.v17-player')){const bar=document.createElement('div');bar.className='v17-player';bar.innerHTML='<button type="button" class="v17-toggle" aria-label="Oynat veya duraklat">▶</button><span class="v17-time">0:00 / 0:00</span><input class="v17-seek" type="range" min="0" max="1000" value="0" aria-label="Ses konumu"><select class="v17-speed" aria-label="Oynatma hızı"><option value=".75">0,75×</option><option value="1" selected>1×</option><option value="1.25">1,25×</option><option value="1.5">1,5×</option><option value="2">2×</option></select><label class="v17-volume">🔊 <input type="range" min="0" max="1" step=".05" value="1" aria-label="Ses düzeyi"></label>';card.append(bar)}})}
let queued=false;new MutationObserver(()=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;enhance()})}).observe(verses,{childList:true,subtree:true});setTimeout(enhance,0);
function sync(){const a=verses.querySelector('.verse.is-playing');verses.querySelectorAll('.v17-player').forEach(b=>{const on=b.closest('.verse')===a;b.classList.toggle('active',on);b.querySelector('.v17-toggle').textContent=on&&!player.paused?'❚❚':'▶';if(on){b.querySelector('.v17-time').textContent=`${fmt(player.currentTime)} / ${fmt(player.duration)}`;b.querySelector('.v17-seek').value=player.duration?Math.round(player.currentTime/player.duration*1000):0}})}
['play','pause','timeupdate','durationchange'].forEach(x=>player.addEventListener(x,sync));
function playFrom(start){const s=current();if(!s)return;const own=++token,auto=$id('ayah-play-mode')?.value!=='manual',reciter=$id('arabic-reciter')?.value||'ar.alafasy';let i=start;const next=()=>{if(own!==token)return;if(i>=s.ayahs.length){clear();sync();setStatus?.(`${s.name} suresi tamamlandı.`);return}const a=s.ayahs[i++];active(a.number,true);player.src=url(s,a,reciter);player.load();player.play().catch(()=>setStatus?.('Ayet sesi başlatılamadı. İnternet bağlantısını denetleyin.'));setStatus?.(`${s.name} ${a.number}. ayet okunuyor.`)};player.onended=()=>auto?next():(clear(),sync());player.onerror=()=>auto&&setTimeout(next,200);next()}
verses.addEventListener('click',async e=>{const p=e.target.closest('[data-v17-play]');if(p){e.preventDefault();e.stopImmediatePropagation();playFrom(Number(p.dataset.v17Play)-1);return}const t=e.target.closest('.v17-toggle');if(t){e.preventDefault();e.stopImmediatePropagation();const card=t.closest('.verse'),n=Number(card.id.split('-')[1]);if(card.classList.contains('is-playing')&&player.src)player.paused?player.play():player.pause();else playFrom(n-1);return}const b=e.target.closest('[data-v17-tafsir]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const box=b.nextElementSibling,open=box.hidden;box.hidden=!open;b.textContent=open?'Ayet tefsirini gizle':'Ayet tefsirini göster';if(!open)return;box.innerHTML='<p>Tefsir hazırlanıyor…</p>';try{tafsirData ||= await fetch('/tefsir.json').then(r=>r.ok?r.json():Promise.reject(Error('Tefsir verisi yüklenemedi')));const ss=tafsirData.find(x=>Number(x.sureID)===state.selected),n=Number(b.dataset.v17Tafsir),entry=ss?.tefsirler?.find(x=>x.ayetler?.map(Number).includes(n));const text=document.createElement('div');text.className='tafsir-text';for(const para of String(entry?.tefsir||'Bu ayet için ayrı bir açıklama bulunamadı.').split('\n'))if(para.trim()){const q=document.createElement('p');q.textContent=para;text.append(q)}box.replaceChildren(Object.assign(document.createElement('strong'),{textContent:`Kur’an Yolu Tefsiri · ${ss?.sureAdi||''}`}),text,Object.assign(document.createElement('small'),{textContent:'Kaynak: Diyanet İşleri Başkanlığı, Kur’an Yolu Tefsiri'}))}catch(err){box.textContent=err.message}},true);
verses.addEventListener('input',e=>{if(e.target.matches('.v17-seek')&&player.duration)player.currentTime=Number(e.target.value)/1000*player.duration;if(e.target.closest('.v17-volume'))player.volume=Number(e.target.value)});verses.addEventListener('change',e=>{if(e.target.matches('.v17-speed'))player.playbackRate=Number(e.target.value)});
const all=$id('play-arabic');if(all)all.onclick=async()=>{const s=current();if(!s)return;token++;const id=chapters[$id('arabic-reciter')?.value]||7;setStatus?.('Tam sure kaydı hazırlanıyor…');try{const r=await fetch(`https://api.quran.com/api/v4/chapter_recitations/${id}/${s.number}?segments=true`);if(!r.ok)throw Error();const f=(await r.json()).audio_file,t=f.timestamps||[];player.src=f.audio_url;player.load();player.ontimeupdate=()=>{const ms=player.currentTime*1000,x=t.find(v=>ms>=v.timestamp_from&&ms<v.timestamp_to);if(x)active(Number(x.verse_key.split(':')[1]));sync()};player.onended=()=>{clear();sync()};await player.play();setStatus?.(`${s.name} suresi seçili kârîden oynatılıyor.`)}catch(_){setStatus?.('Tam sure kaydı başlatılamadı.')}};
function fold(el,title){if(!el||el.parentElement?.classList.contains('v17-fold'))return;const w=document.createElement('section'),h=document.createElement('button');w.className='v17-fold';h.type='button';h.className='v17-fold-head';h.innerHTML=`<span>${title}</span><b>⌄</b>`;el.before(w);w.append(h,el);h.onclick=()=>w.classList.toggle('open')}
fold(document.querySelector('.quran-layout .sidebar'),'Sure seçimi');fold($id('audio-panel'),'Hoca ve ses ayarları');const note=$id('audio-panel')?.querySelector('small');if(note)note.textContent='Türkçe meal: Türkiye Diyanet Vakfı tarafından yayımlanan gerçek insan sesli kayıt. Arapça: seçtiğiniz kârî.';
const cards=document.querySelectorAll('.feature-card');['/menu-quran.jpg','/menu-qibla.jpg','/menu-hadith.jpg'].forEach((src,i)=>cards[i]?.style.setProperty('--feature-image',`url(${src})`));
// APK ve QR kodunu menünün görünür bölümüne al.
const drawer=document.querySelector('.app-drawer'),drawerNav=drawer?.querySelector('.drawer-nav'),download=document.querySelector('.drawer-download');
if(drawerNav&&download)drawerNav.insertAdjacentElement('afterend',download);
})();
